(* [comment removed for export] *)
Lemma otf_keep : forall rax (ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (s0' s1' s2' s3' s4' s5' s6' w1 w2 w3 w4 s6 s5 s4 s3 s2 s1 s0 : word) (F : bvmap 5 word) fc (m : mem),
  rw_cells asegs m (bv_unsigned sp + -96) [C8 w1; C8 w2; C8 w3; C8 w4; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
  96 <= bv_unsigned sp ->
  evt asegs (fun ms' => ms' = MS (mkR (Z_to_bv 64 P_A_OTF_RET) (Z_to_bv 64 (bv_unsigned sp + -96)) gp tp t0 t1 t2 s0' s1'
                                       s4' s3' w3 w4 s2' s1' s0' a7 s2' s3' s4' s5' s6' s7 s8 s9 s10 s11 t3 t4 t5 t6)
                                F (Z_to_bv 64 P_A_FIELDS_INSERT) fc None m (seg_rom asegs))
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -96)) gp tp t0 t1 t2 s0' s1' a0 a1 a2 a3 a4 a5 a6 a7 s2' s3' s4' s5' s6' s7 s8 s9 s10 s11 t3 t4 t5 t6)
