Section SA.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.
  (* [comment removed for export] *)
  Hypothesis EXISTS : token_list_exists_stmt H.

(* [comment removed for export] *)
Tactic Notation "scr_keep_hi" hyp(Hc) "over" hyp(MU) hyp(WM) hyp(RF) hyp(FS) "by" tactic3(tac) :=
  lazymatch type of MU with munch (?X ++ ?XS) ?m ?m' =>
  lazymatch type of Hc with
  | rw_cells _ _ ?A ?cs =>
      let N := fresh "KEEP" in
      assert (N : rw_cells asegs m' A cs)
        by (eapply (rw_cells_transport_scr_hi H HH _ _ X XS m m' A cs RF);
            [ tac | exact Hc | exact MU | exact WM | fit_zsizes; cbn [disjoint_from fst snd cells_size csize Nat.add]; tac | exact FS ]);
      clear Hc; rename N into Hc
  end end.
Tactic Notation "scr_keep" hyp(Hc) "as" constr(OB) "over" hyp(MU) hyp(WM) hyp(RF) hyp(FS) "by" tactic3(tac) :=
  lazymatch type of MU with munch (?X ++ ?XS) ?m ?m' =>
  lazymatch type of Hc with
  | rw_cells _ _ ?A ?cs =>
      let N := fresh "KEEP" in
      assert (N : rw_cells asegs m' A cs)
        by (eapply (rw_cells_transport_scr H HH _ _ X XS m m' A cs RF);
            [ exact (proj1 OB) | exact (proj2 OB) | exact Hc | exact MU | exact WM
            | fit_zsizes; cbn [disjoint_from fst snd cells_size csize Nat.add]; tac | exact FS ]);
      clear Hc; rename N into Hc
  end end.

Definition OTF_SEGA_STACK : Z := 96 + AEXISTS_STACK.   (* [comment removed for export] *)

Definition otf_segA_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (s : as_St H) (LB : list block) (LF : list fframe)
    (P f np vp ecA : Z) (name value : list byte) (S L : list Z) (ns : NS) (ls : LS) (em : gmap Z elt) (lo shi : Z) (m : mem)
    : machine_state -> Prop :=
  fun ms' => exists (kept : bool) t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' w1 w2 w3 w4 XS,
    munch ((lo, bv_unsigned sp) :: XS)%Z m m' /\ Forall (fs_scratch H LF) XS /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ AFieldsC m' (P + 80) S L ns ls em /\ FT m'
    /\ as_RHEAP H s LB m' /\ as_RFS H LF m' /\ ACONST m' /\ stack0 m' lo shi
    /\ if kept then
         ms' = MS (mkR (Z_to_bv 64 P_A_OTF_RET) (Z_to_bv 64 (bv_unsigned sp + -96)) gp tp t0 t1 t2 (Z_to_bv 64 ecA) (Z_to_bv 64 (zlength value))
                       (Z_to_bv 64 (P + 80)) (Z_to_bv 64 f) (Z_to_bv 64 np) (Z_to_bv 64 (zlength name)) (Z_to_bv 64 vp) (Z_to_bv 64 (zlength value)) (Z_to_bv 64 ecA) a7
                       (Z_to_bv 64 vp) (Z_to_bv 64 f) (Z_to_bv 64 (P + 80)) (Z_to_bv 64 P) (Z_to_bv 64 2147450880) s7 s8 s9 s10 s11 t3 t4 t5 t6)
                  F (Z_to_bv 64 P_A_FIELDS_INSERT) fc None m' (seg_rom asegs)
         /\ stk asegs m' lo (bv_unsigned sp + -96)
         /\ otf_frame m' sp ra s0 s1 s2 s3 s4 s5 s6 w1 w2 w3 w4
       else
         ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                  F (ret_pc ra) fc None m' (seg_rom asegs)
         /\ stk asegs m' lo (bv_unsigned sp).

Definition otf_segA_stmt : Prop := forall (s : as_St H) (LB : list block) (LF : list fframe)
    (P f np vp ecA : Z) (mb : byte) (name value : list byte) (S L : list Z) (ns : NS) (ls : LS) (em : gmap Z elt) (lo shi : Z)
    ra sp gp tp t0 t1 t2 s0 s1 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
